{
  "schemaVersion": 4,
  "name": "525 immutable pinned fixture",
  "description": "Synthetic terminal history; no provider ran.",
  "settings": {
    "workingDirectory": {
      "kind": "temp"
    },
    "defaults": {
      "byHarness": {}
    },
    "maxNodeVisits": 10,
    "runDeadlineSeconds": null,
    "structuredTimeoutMs": null,
    "subloopDepthLimit": 8
  },
  "variables": {},
  "nodes": [
    {
      "id": "start",
      "label": "Pinned 525 Start",
      "ui": {
        "x": 0,
        "y": 0
      },
      "kind": "trigger",
      "config": {
        "type": "manual",
        "exposeTo": [
          "ui",
          "api",
          "mcp"
        ]
      }
    },
    {
      "id": "work",
      "label": "Pinned 525 Work",
      "ui": {
        "x": 0,
        "y": 0
      },
      "kind": "inference",
      "config": {
        "session": {
          "policy": "fresh"
        },
        "prompt": {
          "template": "Retain “snapshot” text and unicode 雪.  "
        },
        "input": [],
        "harnessOptions": {
          "sandbox": "workspace-write",
          "approval": "never",
          "configOverrides": {
            "features.plugins": false
          }
        },
        "output": {
          "captureTranscript": "artifact",
          "toMessages": "final",
          "transforms": []
        },
        "timeoutSeconds": 120
      }
    },
    {
      "id": "done",
      "label": "Pinned 525 Done",
      "ui": {
        "x": 0,
        "y": 0
      },
      "kind": "exit",
      "config": {
        "outcome": "success",
        "returns": "none",
        "destinations": [
          {
            "kind": "caller"
          }
        ]
      }
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": {
        "node": "start",
        "port": "out"
      },
      "to": {
        "node": "work",
        "port": "in"
      }
    },
    {
      "id": "b",
      "from": {
        "node": "work",
        "port": "out"
      },
      "to": {
        "node": "done",
        "port": "in"
      }
    }
  ]
}

